_NUM_TOKEN = re.compile(
    r"(?P<dot>\.)?"
    r"(?P<word>(?!\d)[\w\u064B-\u065F\u0670]+)"
    r"(?P<open>\s*\()?"
)

USER_NAMES = set()


def _num_replace(match):
    dot = match.group("dot")
    word = match.group("word")
    open_paren = match.group("open")
    if word in USER_NAMES:
        return match.group(0)
    if dot:
        if open_paren and word in NUM_METHODS:
            return "." + NUM_METHODS[word] + open_paren
        if word in NUM_PROPS:
            return "." + NUM_PROPS[word]
        return match.group(0)
    if word in NUM_CONSTS:
        return NUM_CONSTS[word]
    if word in NUM_FUNCS:
        return NUM_FUNCS[word] + (open_paren or "")
    return match.group(0)


def NUM_SUBSTITUTE(text):
    """يترجم كلمات المكتبة في نص واحد ويُرجع المترجم."""
    if not text:
        return text
    return _NUM_TOKEN.sub(_num_replace, text)
